  (2, 101, 101, 'Zion, UT',          '2025-08-01', 'Second stop', 'Finder Two', 'finder2@example.com',
   '22222222-2222-4222-8222-222222222222', true, 37.2982, -113.0263, 'United States', 'Utah', '2025-08-01'),
-- Rock 102: visible, but no coordinates yet (uploads don't geocode) [C1 NaN distance]
